import '../models/staff.dart';

/// Abstraction over the `staff` collection and its `work_logs` sub-collection.
abstract interface class StaffRepository {
  /// Watch all staff.
  Stream<List<Staff>> watchStaff();

  /// Fetch all staff once.
  Future<List<Staff>> getStaff();

  /// Fetch a single staff member by id.
  Future<Staff?> getStaffMember(String id);

  /// Create a staff member (id auto-generated by Firestore).
  Future<String> addStaff(Staff staff);

  /// Update a staff member.
  Future<void> updateStaff(String id, Staff staff);

  /// Delete a staff member (also deletes their work logs).
  Future<void> deleteStaff(String id);

  /// Watch the work logs of a staff member, most recent first.
  Stream<List<WorkLog>> watchWorkLogs(String staffId);

  /// Add a work log entry to a staff member.
  Future<void> addWorkLog(String staffId, WorkLog log);
}
